# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _validate(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students for contacts")
    for student in students:
        if not (student.email or "").strip():
            raise ProjectError(
                f"no email for {student.display_name}"
            )


def _rows(students: List[Student]) -> list:
    return [
        (s.display_name, s.section, s.email.strip())
        for s in students
    ]


def _join(row, widths) -> str:
    cells = zip(row, widths)
    padded = (cell.ljust(size) for cell, size in cells)
    return "  ".join(padded).rstrip()


# ---
def format_contacts(students) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    ordered = sorted(students, key=lambda s: s.display_name)
    _validate(ordered)
    rows = _rows(ordered)
    widths = [max(map(len, col)) for col in zip(*rows)]
    return [_join(row, widths) for row in rows]
